package dev.rinorsi.editor.registry;

import com.google.gson.*;
import dev.rinorsi.editor.ComponentValidation;
import java.nio.file.*;
import java.util.*;
import net.minecraft.SharedConstants;
import net.minecraft.core.RegistryAccess;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.Bootstrap;

/** Snapshot is generated by live codec derivation, not used as a production schema source. */
public final class ComponentSchemaTest {
    private static net.minecraft.core.HolderLookup.Provider fixtureLookup;
    public static RegistryAccess bootstrap() {
        SharedConstants.tryDetectVersion(); Bootstrap.bootStrap();
        var lookup = net.minecraft.data.registries.VanillaRegistries.createLookup();
        fixtureLookup = lookup;
        BuiltInRegistries.DATA_COMPONENT_INITIALIZERS.build(lookup).forEach(p -> p.apply());
        var builtins = RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);
        return new RegistryAccess() {
            @Override public <E> Optional<net.minecraft.core.Registry<E>> lookup(net.minecraft.resources.ResourceKey<? extends net.minecraft.core.Registry<? extends E>> key) { return builtins.lookup(key); }
            @Override public java.util.stream.Stream<RegistryAccess.RegistryEntry<?>> registries() { return builtins.registries(); }
            @Override public <V> net.minecraft.resources.RegistryOps<V> createSerializationContext(com.mojang.serialization.DynamicOps<V> ops) { return lookup.createSerializationContext(ops); }
        };
    }
    private static int checks;
    public static void main(String[] args) throws Exception {
        var access = bootstrap(); var entries = new JsonArray();
        check(ComponentSchema.VERSION == 2, "schema v2 shape contract");
        var persistent = ComponentSchema.persistentIds();
        for (String id : persistent) {
            var derived = ComponentSchema.derive(id, access); entries.add(derived.entry());
            check(derived.entry().get("source").getAsString().equals("vanilla"), "vanilla source " + id);
            check(derived.entry().has("label_key") && derived.entry().has("default_from_prototypes"), "label and prototype summary " + id);
            check(derived.entry().has("editable") && derived.entry().get("validator_route").getAsString().equals("component_validate"), "editability and validation route " + id);
            check(derived.entry().has("ranges_for_ui"), "numeric field export " + id);
            check(derived.entry().has("coverage"), "coverage " + id);
            check(derived.entry().getAsJsonArray("fields").size() == 1, "root " + id);
            check(derived.entry().toString().length() < 23000, "row budget " + id);
            for (var prototype : derived.entry().getAsJsonArray("prototype_examples")) {
                var request = new JsonObject(); request.addProperty("component", id); request.add("value", prototype.getAsJsonObject().get("value"));
                check(ComponentValidation.validate(request, access).get("ok").getAsBoolean(), "real prototype parses " + id);
            }
        }
        complexComponents(access);
        var pages = RegistryPages.split("component_schema", "test", entries);
        int rows = 0;
        for (var page : pages) {
            check(page.toString().length() <= RegistryPages.MAX_CHARS, "real schema wire page budget");
            check(page.get("offset").getAsInt() == rows, "real schema contiguous offsets");
            rows += page.getAsJsonArray("entries").size();
        }
        check(rows == persistent.size() && pages.getLast().get("done").getAsBoolean(), "all schema rows paginated");
        for (String id : List.of("custom_name", "item_name", "lore", "item_model", "tooltip_style", "unbreakable", "glider", "instrument", "map_color", "map_id", "block_entity_data", "entity_data")) {
            var derived = ComponentSchema.derive(id, access);
            check(!derived.root().json.has("unknown"), "formerly opaque root resolved " + id);
        }
        check(ComponentSchema.derive("lore", access).root().element.json.get("kind").getAsString().equals("text_component"), "lore preserves list of text components");
        check(ComponentSchema.derive("instrument", access).root().alternatives.size() == 1, "instrument inline holder schema");
        var consumable = ComponentSchema.derive("consumable", access).root().fields.get("on_consume_effects").element;
        check(consumable.json.get("kind").getAsString().equals("variants") && consumable.alternatives.size() == BuiltInRegistries.CONSUME_EFFECT_TYPE.size(), "all real consume effect dispatch variants");
        check(ComponentSchema.derive("tool", access).root().fields.get("rules").element.fields.get("blocks").json.get("kind").getAsString().equals("holder_set"), "tool registry holder set");
        check(ComponentSchema.derive("equippable", access).root().fields.get("allowed_entities").json.get("kind").getAsString().equals("holder_set"), "equippable registry holder set");
        var stack = ComponentSchema.derive("max_stack_size", access);
        check(stack.root().json.get("min").getAsInt() == 1 && stack.root().json.get("max").getAsInt() == 99, "stack range from actual codec");
        check(!ComponentSchema.errors(stack, new JsonPrimitive(100), access).isEmpty(), "stack bad boundary has path");
        var food = ComponentSchema.derive("food", access);
        check(food.root().fields.containsKey("nutrition") && food.root().fields.containsKey("saturation"), "record fields extracted");
        check(food.root().fields.get("can_always_eat").json.get("default").getAsBoolean() == false, "actual optional default extracted");
        var errors = ComponentSchema.errors(food, JsonParser.parseString("""
                {"nutrition":-1,"saturation":"invalid"}
                """), access);
        check(errors.toString().contains("$.nutrition") && errors.toString().contains("$.saturation"), "per-path independent failures");
        var enchants = ComponentSchema.derive("enchantments", access);
        check(enchants.root().element.json.get("max").getAsInt() == 255, "enchantment level actual maximum");
        var missing = ComponentSchema.errors(food, new JsonObject(), access);
        check(missing.toString().contains("required"), "missing required field path");
        var badFood = new JsonObject(); badFood.addProperty("component", "food"); badFood.add("value", JsonParser.parseString("""
                {"nutrition":-1,"saturation":"invalid"}
                """));
        badFood.addProperty("requestId", "schema-path-test");
        var detailed = ComponentSchemaValidation.validate(badFood, access);
        check(!detailed.get("ok").getAsBoolean() && detailed.get("path_precision").getAsString().equals("field"), "helper preserves whole-codec failure");
        check(detailed.getAsJsonArray("errors").toString().contains("$.nutrition"), "helper returns real field path");
        var legacy = ComponentValidation.validate(badFood, access);
        var withoutDetails = detailed.deepCopy(); withoutDetails.remove("errors"); withoutDetails.remove("path_precision");
        check(legacy.equals(withoutDetails), "legacy validation fields unchanged");
        var badTool = new JsonObject(); badTool.addProperty("component", "tool"); badTool.add("value", JsonParser.parseString("""
                {"rules":[{"blocks":"minecraft:stone","speed":-1}]}
                """));
        check(ComponentSchemaValidation.validate(badTool, access).getAsJsonArray("errors").toString().contains("$.rules[0].speed"), "nested list path from exact field codec");
        var badDispatch = ComponentSchema.errors(ComponentSchema.derive("consumable", access), JsonParser.parseString("""
                {"on_consume_effects":[{"type":"minecraft:teleport_randomly","diameter":0}]}
                """), access);
        check(badDispatch.toString().contains("$.on_consume_effects[0].diameter"), "dispatch errors follow selected variant field codec");
        var badSnbt = new JsonObject(); badSnbt.addProperty("component", "custom_data"); badSnbt.addProperty("snbt", "{broken:}");
        check(ComponentSchemaValidation.validate(badSnbt, access).get("path_precision").getAsString().equals("component"), "SNBT parser error never assigned fabricated field path");
        var snapshot = new JsonObject(); snapshot.addProperty("mc_version", "26.1.2"); snapshot.addProperty("schema_version", ComponentSchema.VERSION); snapshot.add("components", entries);
        var findings = new JsonArray();
        captureProbe(findings, "tool", "$.rules[0].speed", "data.js numeric schema has no min; core.validateValue allows 0", JsonParser.parseString("""
                {"rules":[{"blocks":"minecraft:stone","speed":0}]}
                """), access);
        captureProbe(findings, "use_cooldown", "$.seconds", "data.js numeric schema has no min; core.validateValue allows 0", JsonParser.parseString("""
                {"seconds":0}
                """), access);
        var book = new JsonObject(); book.addProperty("title", "a".repeat(33)); book.addProperty("author", "test");
        captureProbe(findings, "written_book_content", "$.title", "data.js title string has no max length; core.validateValue allows 33 chars", book, access);
        captureProbe(findings, "max_stack_size", "$", "core.validateValue rejects fractional values for t:int", new JsonPrimitive(1.5), access);
        captureProbe(findings, "fireworks", "$.flight_duration", "data.js int min:0/max:255; core rejects 256", JsonParser.parseString("""
                {"flight_duration":256}
                """), access);
        var manySlots = new JsonArray();
        for (int i = 0; i < 257; i++) manySlots.add(JsonParser.parseString("""
                {"slot":0,"item":{"id":"minecraft:stone"}}
                """));
        captureProbe(findings, "container", "$", "data.js list max:256; core rejects 257 entries (including duplicate slots)", manySlots, access);
        Path path = Path.of("docs/component-schema-26.1.2.json");
        if (args.length > 0 && args[0].equals("--write-snapshot")) Files.writeString(path, new GsonBuilder().serializeNulls().setPrettyPrinting().disableHtmlEscaping().create().toJson(snapshot) + System.lineSeparator());
        else {
            if (args.length > 1 && args[0].equals("--snapshot")) path = Path.of(args[1]);
            JsonElement expected = JsonParser.parseString(Files.readString(path));
            // Compare wire JSON, not Gson Float/Double backing classes (Float.MAX_VALUE
            // widens differently from its shortest serialized decimal representation).
            JsonElement wireSnapshot = JsonParser.parseString(snapshot.toString());
            if (!expected.equals(wireSnapshot)) {
                Path actual = Path.of("logs/backend-g/schema-drift-actual.json");
                Files.createDirectories(actual.getParent());
                Files.writeString(actual, new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(snapshot));
            }
            check(expected.equals(wireSnapshot), "live derivation differs from snapshot; review codec drift, then explicitly regenerate --write-snapshot");
        }
        if (args.length > 1 && args[0].equals("--write-snapshot")) {
            var receipt = new JsonObject(); receipt.add("field_validation", detailed); receipt.add("nested_validation", ComponentSchemaValidation.validate(badTool, access));
            receipt.add("boundary_findings", findings);
            receipt.addProperty("checks", checks); receipt.addProperty("status", "PASSED");
            Files.writeString(Path.of(args[1]), new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(receipt));
        }
        var ranges = new JsonObject();
        for (JsonElement row : entries) ranges.add(row.getAsJsonObject().get("id").getAsString(), row.getAsJsonObject().get("ranges_for_ui"));
        Path rangesPath = Path.of("docs/component-schema-ui-ranges-26.1.2.json");
        var rangesDocument = JsonParser.parseString(Files.readString(rangesPath)).getAsJsonObject();
        if (args.length > 0 && args[0].equals("--write-snapshot")) {
            rangesDocument.add("ranges_for_ui", ranges); rangesDocument.addProperty("schema_version", ComponentSchema.VERSION);
            Files.writeString(rangesPath, new GsonBuilder().serializeNulls().setPrettyPrinting().disableHtmlEscaping().create().toJson(rangesDocument) + System.lineSeparator());
        } else check(rangesDocument.get("ranges_for_ui").equals(JsonParser.parseString(ranges.toString())), "UI numeric ranges artifact drift");
        modComponents(access);
        System.out.println("PASS ComponentSchemaTest " + checks + " checks; " + persistent.size() + " live component schemas, real defaults/ranges/path diagnostics and snapshot drift");
    }
    private static void complexComponents(RegistryAccess access) {
        for (String id : List.of("trim", "provides_trim_material", "profile")) {
            var schema = ComponentSchema.derive(id, access);
            check(schema.entry().get("coverage").getAsString().equals("full"), "complete complex schema " + id);
            JsonElement sample = sample(schema.root(), access);
            check(schema.root().codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), sample).isSuccess(), "schema-generated sample parses " + id + ": " + sample);
        }
        var lock = ComponentSchema.derive("lock", access);
        check(lock.entry().get("coverage").getAsString().equals("partial"), "lock explicitly retains advanced predicate fallback");
        check(lock.entry().getAsJsonArray("unknown_paths").toString().equals("[\"$.predicates\"]"), "lock only advanced predicate values remain unknown");
        var lockInput = new JsonObject(); lockInput.add("items", sample(lock.root().fields.get("items"), access));
        lockInput.add("count", JsonParser.parseString("{\"min\":1,\"max\":2}"));
        var exact = lock.root().fields.get("components");
        check(exact.json.get("value_schema_route").getAsString().equals("component_schema:<component-id>") && !exact.json.get("allow_removal").getAsBoolean(), "exact component maps use component schemas without removals");
        var values = new JsonObject(); var valueSchema = ComponentSchema.derive("damage", access);
        values.add(valueSchema.id(), sample(valueSchema.root(), access)); lockInput.add("components", values);
        check(lock.root().codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), lockInput).isSuccess(), "lock schema-built nonempty sample " + lockInput);
        lockInput.add("count", JsonParser.parseString("{\"min\":2,\"max\":1}"));
        check(!lock.root().codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), lockInput).isSuccess(), "lock inverted inclusive bounds rejected");
        var profile = ComponentSchema.derive("profile", access).root();
        var object = profile.alternatives.stream().filter(n -> n.json.get("kind").getAsString().equals("object")).findFirst().orElseThrow();
        check(object.fields.get("name").json.get("optional").getAsBoolean() && object.fields.get("id").json.get("optional").getAsBoolean(), "profile partial identity fields may be omitted");
        var properties = object.fields.get("properties");
        for (var branch : properties.alternatives) {
            JsonElement value;
            if (branch.json.get("kind").getAsString().equals("map")) {
                var map = new JsonObject(); var textures = new JsonArray(); textures.add("texture-payload"); map.add("textures", textures); value = map;
                int max = branch.json.get("max_size").getAsInt();
                var boundary = new JsonObject();
                for (int i = 0; i < max; i++) boundary.add("key" + i, new JsonArray());
                check(branch.codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), boundary).isSuccess(), "profile map exported size accepted");
                boundary.add("overflow", new JsonArray());
                check(!branch.codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), boundary).isSuccess(), "profile map overflow rejected");
            } else {
                var list = new JsonArray(); var property = sample(branch.element, access).getAsJsonObject();
                property.addProperty("name", "textures"); list.add(property); value = list;
            }
            var input = new JsonObject(); input.add("properties", value);
            check(profile.codec.parse(access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE), input).isSuccess(), "profile textures schema sample " + input);
        }
    }
    private static JsonElement sample(ComponentSchema.Node node, RegistryAccess access) {
        String kind = node.json.get("kind").getAsString();
        if (node.json.has("default")) return node.json.get("default").deepCopy();
        if (kind.equals("holder") || kind.equals("holder_set") || kind.equals("registry")) {
            check(node.json.get("candidate_source").getAsString().equals("runtime_registry") && node.json.get("allow_manual_id").getAsBoolean(), "live candidates permit manual IDs");
            String registry = node.json.get("registry").getAsString();
            check(node.json.get("candidate_route").getAsString().equals(registry), "candidate route matches codec registry");
            var key = net.minecraft.resources.ResourceKey.createRegistryKey(net.minecraft.resources.Identifier.parse(registry));
            var lookup = fixtureLookup.lookupOrThrow(key);
            return new JsonPrimitive(lookup.listElements().findFirst().orElseThrow().key().identifier().toString());
        }
        if (kind.equals("int")) return new JsonPrimitive(node.json.has("min") ? node.json.get("min").getAsInt() : 0);
        if (kind.equals("string")) return new JsonPrimitive("a".repeat(node.json.has("min_length") ? node.json.get("min_length").getAsInt() : 0));
        if (kind.equals("union")) return sample(node.alternatives.getFirst(), access);
        if (kind.equals("object")) {
            var result = new JsonObject();
            node.fields.forEach((name, field) -> { if (!field.json.get("optional").getAsBoolean()) result.add(name, sample(field, access)); });
            return result;
        }
        throw new AssertionError("No schema sample generator for " + node.json);
    }
    private record ModValue(int strength) {}
    private static void modComponents(RegistryAccess access) throws Exception {
        var codec = com.mojang.serialization.codecs.RecordCodecBuilder.<ModValue>create(i -> i.group(
                com.mojang.serialization.Codec.intRange(2, 9).optionalFieldOf("strength", 4).forGetter(ModValue::strength)).apply(i, ModValue::new));
        var structured = net.minecraft.core.component.DataComponentType.<ModValue>builder().persistent(codec).build();
        var opaqueCodec = new com.mojang.serialization.Codec<Integer>() {
            public <T> com.mojang.serialization.DataResult<com.mojang.datafixers.util.Pair<Integer, T>> decode(com.mojang.serialization.DynamicOps<T> ops, T input) { return com.mojang.serialization.Codec.INT.decode(ops, input); }
            public <T> com.mojang.serialization.DataResult<T> encode(Integer value, com.mojang.serialization.DynamicOps<T> ops, T prefix) { return com.mojang.serialization.Codec.INT.encode(value, ops, prefix); }
        };
        var opaque = net.minecraft.core.component.DataComponentType.<Integer>builder().persistent(opaqueCodec).build();
        // Test JVM only: bootstrap freezes built-ins before tests run. Restore that flag immediately.
        var registry = BuiltInRegistries.DATA_COMPONENT_TYPE;
        var frozen = net.minecraft.core.MappedRegistry.class.getDeclaredField("frozen"); frozen.setAccessible(true);
        boolean original = frozen.getBoolean(registry); frozen.setBoolean(registry, false);
        try {
            net.minecraft.core.Registry.register(registry, net.minecraft.resources.Identifier.parse("schema_test:strength"), structured);
            net.minecraft.core.Registry.register(registry, net.minecraft.resources.Identifier.parse("schema_test:opaque"), opaque);
            var bind = net.minecraft.core.Holder.Reference.class.getDeclaredMethod("bindValue", Object.class); bind.setAccessible(true);
            bind.invoke(registry.get(net.minecraft.resources.Identifier.parse("schema_test:strength")).orElseThrow(), structured);
            bind.invoke(registry.get(net.minecraft.resources.Identifier.parse("schema_test:opaque")).orElseThrow(), opaque);
        } finally { frozen.setBoolean(registry, original); }
        check(ComponentSchema.persistentIds().containsAll(List.of("schema_test:strength", "schema_test:opaque")), "bulk enumerator includes registered mod components");
        var derived = ComponentSchema.derive("schema_test:strength", access);
        check(derived.entry().get("source").getAsString().equals("mod:schema_test"), "mod namespace source");
        check(derived.entry().get("editable").getAsString().equals("structured"), "mod record structured editing");
        check(derived.entry().get("label_key").isJsonNull(), "missing mod label never fabricated");
        var range = derived.entry().getAsJsonArray("ranges_for_ui").get(0).getAsJsonObject();
        check(range.get("min").getAsInt() == 2 && range.get("max").getAsInt() == 9 && range.get("default").getAsInt() == 4, "mod ranges and default derived without vanilla table");
        var fallback = ComponentSchema.derive("schema_test:opaque", access);
        check(fallback.entry().get("editable").getAsString().equals("snbt_only"), "opaque mod codec preserves SNBT fallback");
        var request = new JsonObject(); request.addProperty("component", "schema_test:opaque"); request.addProperty("snbt", "7");
        check(ComponentSchemaValidation.validate(request, access).get("ok").getAsBoolean(), "opaque mod SNBT uses actual codec validation");
        request.addProperty("component", "schema_test:strength"); request.remove("snbt"); request.add("value", JsonParser.parseString("{\"strength\":10}"));
        check(!ComponentSchemaValidation.validate(request, access).get("ok").getAsBoolean(), "mod out-of-range value rejected by actual codec");
        var receipt = new JsonObject(); receipt.add("structured", derived.entry()); receipt.add("opaque", fallback.entry());
        Files.createDirectories(Path.of("logs/backend-g"));
        Files.writeString(Path.of("logs/backend-g/schema-mod-evidence.json"), new GsonBuilder().serializeNulls().setPrettyPrinting().serializeNulls().create().toJson(receipt));
    }
    private static void captureProbe(JsonArray out, String id, String path, String ui, JsonElement input, RegistryAccess access) {
        var codec = ComponentValidation.type(id).codec(); var ops = access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);
        var result = codec.parse(ops, input); var row = new JsonObject(); row.addProperty("component", "minecraft:" + id); row.addProperty("path", path);
        row.addProperty("ui_observation", ui); row.addProperty("codec_ok", result.isSuccess());
        result.error().ifPresent(e -> row.addProperty("codec_error", e.message().substring(0, Math.min(1000, e.message().length()))));
        if (result.isSuccess()) {
            @SuppressWarnings("unchecked") var typed = (com.mojang.serialization.Codec<Object>) codec;
            var normalized = typed.encodeStart(ops, result.getOrThrow()).getOrThrow();
            if (normalized.toString().length() < 1800) row.add("normalized", normalized);
        }
        out.add(row);
    }
    private static void check(boolean value, String message) { if (!value) throw new AssertionError(message); checks++; }
}
